import{Z as t,e as o,f as s,a0 as r}from"./chunks/framework.DmpHOl9T.js";const d=JSON.parse('{"title":"reCAPTCHA","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/captchas/recaptcha.md","filePath":"integrations/captchas/recaptcha.md","lastUpdated":1781604764000}'),a={name:"integrations/captchas/recaptcha.md"};function n(i,e,l,h,c,p){return o(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="recaptcha" tabindex="-1">reCAPTCHA <a class="header-anchor" href="#recaptcha" aria-label="Permalink to &quot;reCAPTCHA&quot;">​</a></h1><p>Follow the below steps to connect Formie to Google reCAPTCHA.</p><h3 id="step-1-open-the-captcha-settings" tabindex="-1">Step 1. Open the Captcha Settings <a class="header-anchor" href="#step-1-open-the-captcha-settings" aria-label="Permalink to &quot;Step 1. Open the Captcha Settings&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Spam Protection</strong> → <strong>Captchas</strong>.</li><li>Select <strong>reCAPTCHA</strong> in the left-hand sidebar.</li><li>Turn on <strong>Enabled</strong>.</li></ol><h3 id="step-2-create-your-recaptcha-keys" tabindex="-1">Step 2. Create Your reCAPTCHA Keys <a class="header-anchor" href="#step-2-create-your-recaptcha-keys" aria-label="Permalink to &quot;Step 2. Create Your reCAPTCHA Keys&quot;">​</a></h3><ol><li>Go to the <a href="https://www.google.com/recaptcha/admin" target="_blank" rel="noreferrer">reCAPTCHA Admin console</a> or the <a href="https://console.cloud.google.com/security/recaptcha" target="_blank" rel="noreferrer">Google Cloud reCAPTCHA page</a>.</li><li>Create a new website key for the mode you want to use.</li><li>Use a <strong>score-based</strong> key for <strong>reCAPTCHA v3</strong>.</li><li>Use a <strong>challenge</strong> key for <strong>reCAPTCHA v2 Checkbox</strong>.</li><li>For <strong>reCAPTCHA Enterprise</strong>, create a website key whose type matches the Enterprise key type you want to use in Formie.</li><li>Add the domains where the form will run.</li><li>Save the key.</li><li>Copy the <strong>Site Key</strong>.</li><li>Open the key details and use <strong>Use Legacy Key</strong> to reveal the <strong>legacy secret key</strong> for third-party integrations such as Formie.</li><li>If you are using <strong>reCAPTCHA Enterprise</strong>, also note your Google Cloud <strong>Project ID</strong>.</li></ol><h3 id="step-3-connect-formie-to-recaptcha" tabindex="-1">Step 3. Connect Formie to reCAPTCHA <a class="header-anchor" href="#step-3-connect-formie-to-recaptcha" aria-label="Permalink to &quot;Step 3. Connect Formie to reCAPTCHA&quot;">​</a></h3><ol><li>Choose the <strong>reCAPTCHA Type</strong> in Formie.</li><li>Paste the <strong>reCAPTCHA Site Key</strong> into the <strong>reCAPTCHA Site Key</strong> field.</li><li>Paste the <strong>legacy secret key</strong> into the <strong>reCAPTCHA Secret Key</strong> field.</li><li>If you are using <strong>reCAPTCHA Enterprise</strong>, select the <strong>Enterprise Key Type</strong> that matches the key you created and enter the <strong>Project ID</strong>.</li><li>Optionally configure the other settings that apply to your chosen mode, such as <strong>Minimum Score</strong>, <strong>Badge Type</strong>, <strong>Theme</strong>, <strong>Size</strong>, <strong>Action</strong>, <strong>Language</strong>, and <strong>Script Loading Method</strong>.</li><li>Save the captcha settings.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to protect.</li><li>Enable <strong>reCAPTCHA</strong> for that form.</li><li>For multi-page forms, turn on <strong>Show on All Pages</strong> if reCAPTCHA should run on every page instead of only the final submit step.</li><li>For <strong>reCAPTCHA v3</strong> or <strong>Enterprise score-based</strong> keys, optionally override the global <strong>Action</strong> or <strong>Minimum Score</strong> for this form only. Leave these blank to inherit the values from <strong>Settings → Spam Protection</strong>.</li><li>Save the form.</li></ol><p>For most forms, <strong>reCAPTCHA v3</strong> is the best starting point. Use the checkbox or Enterprise challenge modes only when you need a visible challenge.</p><h2 id="score-based-challenges-and-low-scores" tabindex="-1">Score-Based Challenges and Low Scores <a class="header-anchor" href="#score-based-challenges-and-low-scores" aria-label="Permalink to &quot;Score-Based Challenges and Low Scores&quot;">​</a></h2><p>reCAPTCHA v3 and <strong>Enterprise score-based</strong> modes return a score when the user submits. Formie compares that score to your <strong>Minimum Score</strong> threshold (globally under <strong>Settings → Spam Protection</strong>, or per form when you override it). Submissions below the threshold are treated as spam.</p><p>Formie does <strong>not</strong> support a second captcha as a fallback when a score is too low — for example, automatically showing a v2 checkbox after Enterprise returns a low score. That would require different API keys, a different user flow, and server-side &quot;soft fail&quot; handling that Formie does not provide today.</p><p>If score-based protection is too aggressive, try one of these instead:</p><ol><li><strong>Lower the minimum score</strong> — start around <code>0.5</code> and adjust based on your traffic.</li><li><strong>Switch to a visible challenge</strong> — use <strong>reCAPTCHA v2 Checkbox</strong>, <strong>reCAPTCHA v2 Invisible</strong>, or an <strong>Enterprise</strong> key type of <strong>Checkbox</strong> or <strong>Policy</strong> when you want users to complete a challenge up front.</li><li><strong>Use another provider</strong> — <a href="/integrations/captchas/cloudflare-turnstile">Cloudflare Turnstile</a> or <a href="/integrations/captchas/friendly-captcha">Friendly Captcha</a> may fit your UX and compliance needs better.</li></ol><p>For <strong>Enterprise</strong> keys migrated from classic reCAPTCHA in Google Cloud, you can usually keep your existing <strong>reCAPTCHA Type</strong> in Formie after migration. Switch to <strong>reCAPTCHA Enterprise</strong> in Formie when you want Enterprise-specific key types or features. Key migration itself happens in Google&#39;s console, not in Formie.</p><h2 id="cookie-consent-and-deferred-loading" tabindex="-1">Cookie Consent and Deferred Loading <a class="header-anchor" href="#cookie-consent-and-deferred-loading" aria-label="Permalink to &quot;Cookie Consent and Deferred Loading&quot;">​</a></h2><p>Google reCAPTCHA loads third-party scripts that may require consent under GDPR and similar regulations. Formie does not integrate directly with consent management platforms (Cookiebot, OneTrust, Klaro, and so on).</p><p>To delay captcha initialisation until consent is granted:</p><ol><li>Render the form with automatic initialisation turned off:</li></ol><div class="language-twig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">twig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ craft.formie.renderForm(form, {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    initJs: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}) }}</span></span></code></pre></div><p>For <a href="/theming/custom-rendering">custom rendering</a>, set <code>data-formie-init=&quot;false&quot;</code> on the <code>&lt;form&gt;</code> element instead.</p><ol start="2"><li><p>Output Formie&#39;s assets as usual with <code>craft.formie.formAssets(form)</code> or <code>craft.formie.frontendAssets()</code>.</p></li><li><p>After your consent banner grants the relevant category, initialise Formie from your own bundle:</p></li></ol><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { formie } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@verbb/formie-browser&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> formie</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  element: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;[data-formie-form]&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>Until you call <code>formie()</code>, captcha scripts are not loaded and captchas are not mounted. Users cannot complete a protected submit until initialisation runs.</p><p>If consent is a hard requirement and you want to avoid Google scripts entirely, consider <a href="/integrations/captchas/friendly-captcha">Friendly Captcha</a> or another provider that fits your compliance model.</p><p>See also <a href="/templates/render-options#initjs">Render Options — <code>initJs</code></a> and the <a href="https://docs.verbb.io/formie/browser/behavior/manual-initialization" target="_blank" rel="noreferrer">Browser package manual initialisation guide</a>.</p><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Submit through the site and check the resulting submission and spam state. A saved credential alone does not verify the visitor-facing challenge or server-side check.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>`,31)])])}const m=t(a,[["render",n]]);export{d as __pageData,m as default};
